export const envelope = [15, 19, 15];

export default function build(api) {
  const [W, H, D] = api.size;
  const SEAT_Y = 3;

  function getBase(blockStr) {
    if (!blockStr) return "minecraft:stone_bricks";
    const idx = blockStr.indexOf("[");
    return idx === -1 ? blockStr : blockStr.slice(0, idx);
  }

  function makeStairs(baseStr, facing = "north", half = "bottom", shape = "straight") {
    const id = getBase(baseStr);
    return `${id}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function makeSlab(baseStr, type = "bottom") {
    const id = getBase(baseStr);
    return `${id}[type=${type}]`;
  }

  function makeLog(baseStr, axis = "y") {
    const id = getBase(baseStr);
    return `${id}[axis=${axis}]`;
  }

  function makeTrapdoor(baseStr, facing = "north", half = "bottom", open = false) {
    const id = getBase(baseStr);
    return `${id}[facing=${facing},half=${half},open=${open}]`;
  }

  function setSafe(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  const { theme } = api;
  const stonePrimary = theme.stone.primary;
  const stoneAccent = theme.stone.accent || stonePrimary;
  const stoneStairs = theme.stone.stairs || stonePrimary;
  const stoneSlab = theme.stone.slab || stonePrimary;
  const stoneWall = theme.stone.wall || stonePrimary;
  const stoneRevetment = theme.ground.revetment || stonePrimary;
  const stonePavement = theme.ground.pavement || stonePrimary;

  const woodPlanks = theme.wood.planks;
  const woodLog = theme.wood.log;
  const woodStripped = theme.wood.stripped || woodLog;
  const woodStairs = theme.wood.stairs || woodPlanks;
  const woodSlab = theme.wood.slab || woodPlanks;
  const woodFence = theme.wood.fence;
  const woodTrapdoor = theme.wood.trapdoor || woodPlanks;

  const roofStairs = theme.roof.stairs || woodStairs;
  const roofSlab = theme.roof.slab || woodSlab;
  const roofSolid = theme.roof.solid || woodPlanks;

  // -------------------------------------------------------------------------
  // 1. FOUNDATION & PLINTH (Conforming directly to real terrain heightmap)
  // -------------------------------------------------------------------------
  const foundationMap = new Map();

  // Main 9x9 raised platform (x: 3..11, z: 3..11)
  for (let x = 3; x <= 11; x++) {
    for (let z = 3; z <= 11; z++) {
      const isBorder = x === 3 || x === 11 || z === 3 || z === 11;
      let surface = isBorder ? stonePrimary : woodPlanks;

      // Bell acoustic resonator ring in floor center
      if (!isBorder && x >= 6 && x <= 8 && z >= 6 && z <= 8) {
        surface = x === 7 && z === 7 ? stonePrimary : stoneAccent;
      }

      // Stone soseki (column base footings)
      if ((x === 4 || x === 10) && (z === 4 || z === 10)) {
        surface = stoneAccent;
      }

      foundationMap.set(`${x},${z}`, {
        targetTopY: SEAT_Y + 1,
        surface,
        sub: isBorder ? stoneRevetment : stonePrimary,
      });
    }
  }

  // Front access steps (North side: z = 0..2)
  for (let x = 5; x <= 9; x++) {
    const z = 2;
    const isMainStair = x >= 6 && x <= 8;
    foundationMap.set(`${x},${z}`, {
      targetTopY: SEAT_Y,
      surface: isMainStair ? makeStairs(stoneStairs, "south", "bottom") : stonePrimary,
      sub: stoneRevetment,
    });
  }
  for (let x = 6; x <= 8; x++) {
    for (let z = 0; z <= 1; z++) {
      foundationMap.set(`${x},${z}`, {
        targetTopY: SEAT_Y,
        surface: stonePavement,
        sub: stoneRevetment,
      });
    }
  }

  // Step skirts on perimeter
  for (let z = 5; z <= 9; z++) {
    for (const x of [2, 12]) {
      foundationMap.set(`${x},${z}`, {
        targetTopY: SEAT_Y,
        surface: makeSlab(stoneSlab, "bottom"),
        sub: stoneRevetment,
      });
    }
  }
  for (let x = 5; x <= 9; x++) {
    const z = 12;
    foundationMap.set(`${x},${z}`, {
      targetTopY: SEAT_Y,
      surface: makeSlab(stoneSlab, "bottom"),
      sub: stoneRevetment,
    });
  }

  // Render foundation columns conforming to terrain
  for (const [key, data] of foundationMap.entries()) {
    const [x, z] = key.split(",").map(Number);
    const gh = Math.round(api.heightAt(x, z));
    const groundY = Math.max(0, SEAT_Y + gh);
    const topY = Math.max(data.targetTopY, groundY);

    for (let y = groundY; y <= topY; y++) {
      if (y === topY) {
        setSafe(x, y, z, data.surface);
      } else {
        setSafe(x, y, z, data.sub);
      }
    }
  }

  // -------------------------------------------------------------------------
  // 2. TIMBER POSTS (Hashira)
  // -------------------------------------------------------------------------
  const postPositions = [
    [4, 4],
    [10, 4],
    [4, 10],
    [10, 10],
  ];

  for (const [px, pz] of postPositions) {
    for (let y = SEAT_Y + 2; y <= SEAT_Y + 8; y++) {
      setSafe(px, y, pz, makeLog(woodLog, "y"));
    }
  }

  // -------------------------------------------------------------------------
  // 3. BALUSTRADE / RAILINGS (Kōran)
  // -------------------------------------------------------------------------
  const railY = SEAT_Y + 2;
  const railTopY = SEAT_Y + 3;

  for (let z = 5; z <= 9; z++) {
    setSafe(4, railY, z, woodFence);
    setSafe(4, railTopY, z, makeTrapdoor(woodTrapdoor, "west", "bottom"));
    setSafe(10, railY, z, woodFence);
    setSafe(10, railTopY, z, makeTrapdoor(woodTrapdoor, "east", "bottom"));
  }
  for (let x = 5; x <= 9; x++) {
    setSafe(x, railY, 10, woodFence);
    setSafe(x, railTopY, 10, makeTrapdoor(woodTrapdoor, "south", "bottom"));
  }
  // North front railings with central gateway (x: 6..8 open)
  setSafe(5, railY, 4, woodFence);
  setSafe(5, railTopY, 4, makeTrapdoor(woodTrapdoor, "north", "bottom"));
  setSafe(9, railY, 4, woodFence);
  setSafe(9, railTopY, 4, makeTrapdoor(woodTrapdoor, "north", "bottom"));

  // -------------------------------------------------------------------------
  // 4. STONE LANTERNS (Tōrō) at approaches
  // -------------------------------------------------------------------------
  const lanternSpots = [
    [3, 2],
    [11, 2],
    [3, 12],
    [11, 12],
  ];
  for (const [lx, lz] of lanternSpots) {
    setSafe(lx, SEAT_Y + 1, lz, stonePrimary);
    setSafe(lx, SEAT_Y + 2, lz, stoneWall);
    setSafe(lx, SEAT_Y + 3, lz, "minecraft:lantern");
    setSafe(lx, SEAT_Y + 4, lz, makeSlab(stoneSlab, "bottom"));
  }

  // -------------------------------------------------------------------------
  // 5. BEAMS & BRACKET COMPLEXES (Nuki & Kumimono)
  // -------------------------------------------------------------------------
  // Lower arch brackets at y = SEAT_Y + 5
  setSafe(4, SEAT_Y + 5, 5, makeStairs(woodStairs, "north", "top"));
  setSafe(4, SEAT_Y + 5, 9, makeStairs(woodStairs, "south", "top"));
  setSafe(10, SEAT_Y + 5, 5, makeStairs(woodStairs, "north", "top"));
  setSafe(10, SEAT_Y + 5, 9, makeStairs(woodStairs, "south", "top"));
  setSafe(5, SEAT_Y + 5, 10, makeStairs(woodStairs, "west", "top"));
  setSafe(9, SEAT_Y + 5, 10, makeStairs(woodStairs, "east", "top"));
  setSafe(5, SEAT_Y + 5, 4, makeStairs(woodStairs, "west", "top"));
  setSafe(9, SEAT_Y + 5, 4, makeStairs(woodStairs, "east", "top"));

  // Upper perimeter tie beams at y = SEAT_Y + 8
  const beamY = SEAT_Y + 8;
  for (let x = 3; x <= 11; x++) {
    setSafe(x, beamY, 4, makeLog(woodLog, "x"));
    setSafe(x, beamY, 10, makeLog(woodLog, "x"));
  }
  for (let z = 3; z <= 11; z++) {
    setSafe(4, beamY, z, makeLog(woodLog, "z"));
    setSafe(10, beamY, z, makeLog(woodLog, "z"));
  }

  // Cross beams supporting the central bell
  for (let x = 4; x <= 10; x++) {
    setSafe(x, beamY, 7, makeLog(woodLog, "x"));
  }
  for (let z = 4; z <= 10; z++) {
    setSafe(7, beamY, z, makeLog(woodLog, "z"));
  }

  // Corner timber braces
  setSafe(5, beamY, 5, woodPlanks);
  setSafe(9, beamY, 5, woodPlanks);
  setSafe(5, beamY, 9, woodPlanks);
  setSafe(9, beamY, 9, woodPlanks);

  // Stepped bracket arms (Dougong) extending outwards
  const bracketY = SEAT_Y + 8;
  setSafe(3, bracketY, 4, makeLog(woodLog, "x"));
  setSafe(4, bracketY, 3, makeLog(woodLog, "z"));
  setSafe(11, bracketY, 4, makeLog(woodLog, "x"));
  setSafe(10, bracketY, 3, makeLog(woodLog, "z"));
  setSafe(3, bracketY, 10, makeLog(woodLog, "x"));
  setSafe(4, bracketY, 11, makeLog(woodLog, "z"));
  setSafe(11, bracketY, 10, makeLog(woodLog, "x"));
  setSafe(10, bracketY, 11, makeLog(woodLog, "z"));

  const bracketTopY = SEAT_Y + 9;
  setSafe(3, bracketTopY, 3, woodPlanks);
  setSafe(11, bracketTopY, 3, woodPlanks);
  setSafe(3, bracketTopY, 11, woodPlanks);
  setSafe(11, bracketTopY, 11, woodPlanks);

  // -------------------------------------------------------------------------
  // 6. THE BONSHŌ (Great Bronze Temple Bell)
  // -------------------------------------------------------------------------
  // Top suspension hub and Ryūzu (dragon loop)
  setSafe(7, SEAT_Y + 8, 7, "minecraft:cut_copper");
  setSafe(7, SEAT_Y + 7, 7, "minecraft:chain[axis=y]");

  // Kasagata (Bell Crown / Dome) at y = SEAT_Y + 6
  const crownY = SEAT_Y + 6;
  setSafe(7, crownY, 7, "minecraft:weathered_cut_copper");
  setSafe(6, crownY, 7, makeStairs("minecraft:weathered_cut_copper_stairs", "east", "bottom"));
  setSafe(8, crownY, 7, makeStairs("minecraft:weathered_cut_copper_stairs", "west", "bottom"));
  setSafe(7, crownY, 6, makeStairs("minecraft:weathered_cut_copper_stairs", "south", "bottom"));
  setSafe(7, crownY, 8, makeStairs("minecraft:weathered_cut_copper_stairs", "north", "bottom"));
  setSafe(6, crownY, 6, makeSlab("minecraft:weathered_cut_copper_slab", "bottom"));
  setSafe(8, crownY, 6, makeSlab("minecraft:weathered_cut_copper_slab", "bottom"));
  setSafe(6, crownY, 8, makeSlab("minecraft:weathered_cut_copper_slab", "bottom"));
  setSafe(8, crownY, 8, makeSlab("minecraft:weathered_cut_copper_slab", "bottom"));

  // Chichinoma (Studded upper barrel) at y = SEAT_Y + 5
  const bodyY = SEAT_Y + 5;
  setSafe(7, bodyY, 7, "minecraft:weathered_cut_copper");
  setSafe(6, bodyY, 7, "minecraft:weathered_cut_copper");
  setSafe(8, bodyY, 7, "minecraft:weathered_cut_copper");
  setSafe(7, bodyY, 6, "minecraft:weathered_cut_copper");
  setSafe(7, bodyY, 8, "minecraft:weathered_cut_copper");
  setSafe(6, bodyY, 6, "minecraft:exposed_cut_copper");
  setSafe(8, bodyY, 6, "minecraft:exposed_cut_copper");
  setSafe(6, bodyY, 8, "minecraft:exposed_cut_copper");
  setSafe(8, bodyY, 8, "minecraft:exposed_cut_copper");

  // Koma-no-tsume (Flared rim) & Tsukiza (Lotus striking target) at y = SEAT_Y + 4
  const rimY = SEAT_Y + 4;
  setSafe(6, rimY, 7, "minecraft:weathered_cut_copper");
  setSafe(8, rimY, 7, "minecraft:weathered_cut_copper");
  setSafe(7, rimY, 8, "minecraft:weathered_cut_copper");
  setSafe(7, rimY, 6, "minecraft:cut_copper"); // Tsukiza striking target
  setSafe(6, rimY, 6, makeStairs("minecraft:weathered_cut_copper_stairs", "south", "top"));
  setSafe(8, rimY, 6, makeStairs("minecraft:weathered_cut_copper_stairs", "south", "top"));
  setSafe(6, rimY, 8, makeStairs("minecraft:weathered_cut_copper_stairs", "north", "top"));
  setSafe(8, rimY, 8, makeStairs("minecraft:weathered_cut_copper_stairs", "north", "top"));

  // -------------------------------------------------------------------------
  // 7. THE SHUMOKU (Suspended Swinging Striker Log)
  // -------------------------------------------------------------------------
  const strikerY = SEAT_Y + 4;
  setSafe(7, strikerY, 2, makeLog(woodStripped, "z"));
  setSafe(7, strikerY, 3, makeLog(woodStripped, "z"));
  setSafe(7, strikerY, 4, makeLog(woodStripped, "z"));
  setSafe(7, strikerY, 5, makeLog(woodLog, "z")); // Striker mallet head facing Tsukiza

  // Suspension chains from crossbeams down to log
  for (let y = SEAT_Y + 5; y <= SEAT_Y + 7; y++) {
    setSafe(7, y, 2, "minecraft:chain[axis=y]");
    setSafe(7, y, 4, "minecraft:chain[axis=y]");
  }
  // Pull rope hanging down from rear
  setSafe(7, SEAT_Y + 3, 2, woodFence);
  setSafe(7, SEAT_Y + 2, 2, makeTrapdoor(woodTrapdoor, "north", "bottom"));

  // -------------------------------------------------------------------------
  // 8. THE IRIMOYA ROOF (Hip-and-Gable with Sweeping Eaves)
  // -------------------------------------------------------------------------
  // Layer y = SEAT_Y + 9 (y = 12): Ceiling & Deep Eave Overhang
  const roofY0 = SEAT_Y + 9;
  for (let x = 3; x <= 11; x++) {
    for (let z = 3; z <= 11; z++) {
      setSafe(x, roofY0, z, makeSlab(woodSlab, "top"));
    }
  }
  for (let x = 1; x <= 13; x++) {
    setSafe(x, roofY0, 0, makeSlab(roofSlab, "bottom"));
    setSafe(x, roofY0, 14, makeSlab(roofSlab, "bottom"));
    setSafe(x, roofY0, 1, makeSlab(roofSlab, "top"));
    setSafe(x, roofY0, 13, makeSlab(roofSlab, "top"));
  }
  for (let z = 1; z <= 13; z++) {
    setSafe(0, roofY0, z, makeSlab(roofSlab, "bottom"));
    setSafe(14, roofY0, z, makeSlab(roofSlab, "bottom"));
    setSafe(1, roofY0, z, makeSlab(roofSlab, "top"));
    setSafe(13, roofY0, z, makeSlab(roofSlab, "top"));
  }

  // Layer y = SEAT_Y + 10 (y = 13): Lower Slope & Upturned Sori Corners
  const roofY1 = SEAT_Y + 10;
  // Four corner sori tips
  setSafe(0, roofY1, 0, makeSlab(roofSlab, "bottom"));
  setSafe(14, roofY1, 0, makeSlab(roofSlab, "bottom"));
  setSafe(0, roofY1, 14, makeSlab(roofSlab, "bottom"));
  setSafe(14, roofY1, 14, makeSlab(roofSlab, "bottom"));

  for (let x = 2; x <= 12; x++) {
    setSafe(x, roofY1, 1, makeStairs(roofStairs, "south", "bottom"));
    setSafe(x, roofY1, 13, makeStairs(roofStairs, "north", "bottom"));
  }
  for (let z = 2; z <= 12; z++) {
    setSafe(1, roofY1, z, makeStairs(roofStairs, "east", "bottom"));
    setSafe(13, roofY1, z, makeStairs(roofStairs, "west", "bottom"));
  }
  setSafe(1, roofY1, 1, makeStairs(roofStairs, "south", "bottom", "outer_left"));
  setSafe(13, roofY1, 1, makeStairs(roofStairs, "south", "bottom", "outer_right"));
  setSafe(1, roofY1, 13, makeStairs(roofStairs, "north", "bottom", "outer_right"));
  setSafe(13, roofY1, 13, makeStairs(roofStairs, "north", "bottom", "outer_left"));

  for (let x = 2; x <= 12; x++) {
    for (let z = 2; z <= 12; z++) {
      setSafe(x, roofY1, z, roofSolid);
    }
  }

  // Layer y = SEAT_Y + 11 (y = 14): Mid Slope
  const roofY2 = SEAT_Y + 11;
  for (let x = 3; x <= 11; x++) {
    setSafe(x, roofY2, 2, makeStairs(roofStairs, "south", "bottom"));
    setSafe(x, roofY2, 12, makeStairs(roofStairs, "north", "bottom"));
  }
  for (let z = 3; z <= 11; z++) {
    setSafe(2, roofY2, z, makeStairs(roofStairs, "east", "bottom"));
    setSafe(12, roofY2, z, makeStairs(roofStairs, "west", "bottom"));
  }
  setSafe(2, roofY2, 2, makeStairs(roofStairs, "south", "bottom", "outer_left"));
  setSafe(12, roofY2, 2, makeStairs(roofStairs, "south", "bottom", "outer_right"));
  setSafe(2, roofY2, 12, makeStairs(roofStairs, "north", "bottom", "outer_right"));
  setSafe(12, roofY2, 12, makeStairs(roofStairs, "north", "bottom", "outer_left"));

  for (let x = 3; x <= 11; x++) {
    for (let z = 3; z <= 11; z++) {
      setSafe(x, roofY2, z, roofSolid);
    }
  }

  // Layer y = SEAT_Y + 12 (y = 15): Irimoya Transition - Hip & Gable
  const roofY3 = SEAT_Y + 12;
  for (let x = 3; x <= 11; x++) {
    setSafe(x, roofY3, 3, makeStairs(roofStairs, "south", "bottom"));
    setSafe(x, roofY3, 11, makeStairs(roofStairs, "north", "bottom"));
  }
  for (let z = 4; z <= 10; z++) {
    setSafe(3, roofY3, z, z === 7 ? makeLog(woodLog, "y") : woodPlanks);
    setSafe(11, roofY3, z, z === 7 ? makeLog(woodLog, "y") : woodPlanks);
  }
  setSafe(2, roofY3, 3, makeStairs(roofStairs, "south", "top"));
  setSafe(2, roofY3, 11, makeStairs(roofStairs, "north", "top"));
  setSafe(12, roofY3, 3, makeStairs(roofStairs, "south", "top"));
  setSafe(12, roofY3, 11, makeStairs(roofStairs, "north", "top"));

  for (let x = 4; x <= 10; x++) {
    for (let z = 4; z <= 10; z++) {
      setSafe(x, roofY3, z, roofSolid);
    }
  }

  // Layer y = SEAT_Y + 13 (y = 16): Upper Hip & Gable Wall
  const roofY4 = SEAT_Y + 13;
  for (let x = 3; x <= 11; x++) {
    setSafe(x, roofY4, 4, makeStairs(roofStairs, "south", "bottom"));
    setSafe(x, roofY4, 10, makeStairs(roofStairs, "north", "bottom"));
  }
  setSafe(3, roofY4, 5, makeStairs(roofStairs, "south", "bottom"));
  setSafe(3, roofY4, 9, makeStairs(roofStairs, "north", "bottom"));
  setSafe(11, roofY4, 5, makeStairs(roofStairs, "south", "bottom"));
  setSafe(11, roofY4, 9, makeStairs(roofStairs, "north", "bottom"));
  for (let z = 6; z <= 8; z++) {
    setSafe(3, roofY4, z, woodPlanks);
    setSafe(11, roofY4, z, woodPlanks);
  }

  for (let x = 4; x <= 10; x++) {
    for (let z = 5; z <= 9; z++) {
      setSafe(x, roofY4, z, roofSolid);
    }
  }

  // Layer y = SEAT_Y + 14 (y = 17): Gable Apex & Ridge Base
  const roofY5 = SEAT_Y + 14;
  for (let x = 3; x <= 11; x++) {
    setSafe(x, roofY5, 5, makeStairs(roofStairs, "south", "bottom"));
    setSafe(x, roofY5, 9, makeStairs(roofStairs, "north", "bottom"));
  }
  setSafe(3, roofY5, 6, makeStairs(roofStairs, "south", "bottom"));
  setSafe(3, roofY5, 8, makeStairs(roofStairs, "north", "bottom"));
  setSafe(3, roofY5, 7, roofSolid);
  setSafe(11, roofY5, 6, makeStairs(roofStairs, "south", "bottom"));
  setSafe(11, roofY5, 8, makeStairs(roofStairs, "north", "bottom"));
  setSafe(11, roofY5, 7, roofSolid);

  for (let x = 4; x <= 10; x++) {
    for (let z = 6; z <= 8; z++) {
      setSafe(x, roofY5, z, roofSolid);
    }
  }

  // Layer y = SEAT_Y + 15 (y = 18): Main Ridge (Ōmune) & Onigawara Finials
  const roofY6 = SEAT_Y + 15;
  setSafe(2, roofY6, 7, makeStairs(roofStairs, "east", "bottom")); // West Onigawara
  setSafe(12, roofY6, 7, makeStairs(roofStairs, "west", "bottom")); // East Onigawara
  for (let x = 3; x <= 11; x++) {
    setSafe(x, roofY6, 7, makeSlab(roofSlab, "bottom"));
  }
  for (let x = 4; x <= 10; x++) {
    setSafe(x, roofY6, 6, makeStairs(roofStairs, "south", "bottom"));
    setSafe(x, roofY6, 8, makeStairs(roofStairs, "north", "bottom"));
  }
  setSafe(7, roofY6, 7, stoneAccent); // Central peak crest

  return {
    name: "bell_pavilion",
    seatY: SEAT_Y,
    anchors: {
      front: [7, SEAT_Y + 1, 0],
      door: [7, SEAT_Y + 1, 2],
      bell: [7, SEAT_Y + 5, 7],
    },
  };
}
